def check_subarray_sum(nums, k):
    n = len(nums)
    for i in range(n):
        total = nums[i]
        for j in range(i + 1, n):
            total += nums[j]                     # recompute the sum for every subarray
            if k == 0:
                if total == 0:
                    return True
            elif total % k == 0:
                return True
    return False

