public class Main {
    static boolean checkSubarraySum(int[] nums, int k) {
        Map<Long, Integer> seen = new HashMap<>();
        seen.put(0L, -1);                     // seed: empty prefix at index -1
        long total = 0;
        for (int i = 0; i < nums.length; i++) {
            total += nums[i];
            long rem = k != 0 ? total % k : total;
            if (seen.containsKey(rem)) {
                if (i - seen.get(rem) >= 2) return true;    // far enough apart
            } else {
                seen.put(rem, i);
            }
        }
        return false;
    }
}

