#include <bits/stdc++.h>
using namespace std;

bool checkSubarraySum(vector<int>& nums, int k) {
    unordered_map<long long,int> seen;
    seen[0] = -1;                             // seed: empty prefix at index -1
    long long total = 0;
    for (int i = 0; i < (int)nums.size(); i++) {
        total += nums[i];
        long long rem = k != 0 ? total % k : total;
        auto it = seen.find(rem);
        if (it != seen.end()) {
            if (i - it->second >= 2) return true;             // far enough apart
        } else {
            seen[rem] = i;
        }
    }
    return false;
}
